const body = $input.first().json.body || $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenIds) staticData.seenIds = {};
if (!staticData.sessions) staticData.sessions = {};

const messages = [];
for (const entry of body.entry || []) {
  for (const change of entry.changes || []) {
    const value = change.value || {};
    for (const msg of value.messages || []) {
      if (staticData.seenIds[msg.id]) continue;
      staticData.seenIds[msg.id] = Date.now();
      let text = null;
      if (msg.type === 'text') text = msg.text?.body || null;
      if (msg.type === 'button') text = msg.button?.text || msg.button?.payload || null;
      if (msg.type === 'interactive') {
        text = msg.interactive?.button_reply?.title
          || msg.interactive?.list_reply?.title
          || null;
      }
      if (!text) continue;
      messages.push({
        from: String(msg.from),
        id: msg.id,
        text: String(text).trim(),
        timestamp: msg.timestamp,
      });
    }
  }
}

const cutoff = Date.now() - 3600_000;
for (const [k, ts] of Object.entries(staticData.seenIds)) {
  if (ts < cutoff) delete staticData.seenIds[k];
}

if (!messages.length) return [];
return messages.map((m) => ({ json: m }));

const item = $input.first().json;
const from = item.from;
const userText = item.text;
const messageId = item.id;

const BOT_BASE = String($env.BOT_API_BASE_URL || '').replace(/\/$/, '');
const BOT_KEY = String($env.BOT_API_KEY || '');
const OPENAI_KEY = String($env.OPENAI_API_KEY || '');
const OPENAI_MODEL = String($env.OPENAI_MODEL || 'deepseek/deepseek-chat');
const OPENAI_FALLBACK_MODELS = String($env.OPENAI_FALLBACK_MODELS || 'deepseek/deepseek-v3.2,openai/gpt-4o-mini');
const OPENAI_BASE = String($env.OPENAI_BASE_URL || 'https://api.openai.com/v1').replace(/\/$/, '');
const REGISTER_URL = String($env.PICKLEVIBES_REGISTER_URL || 'https://picklevibes.hk');
const MODEL_CHAIN = [OPENAI_MODEL, ...OPENAI_FALLBACK_MODELS.split(',')]
  .map((m) => String(m || '').trim())
  .filter(Boolean)
  .filter((m, i, arr) => arr.indexOf(m) === i);

if (!BOT_BASE || !BOT_KEY) {
  return [{ json: { from, reply: '系統尚未設定 Bot API，請稍後再試。', messageId } }];
}
if (!OPENAI_KEY) {
  return [{ json: { from, reply: '系統尚未設定 LLM，請稍後再試。', messageId } }];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
if (!staticData.pendingBookings) staticData.pendingBookings = {};

const sessionKey = from;
if (!staticData.sessions[sessionKey]) staticData.sessions[sessionKey] = [];
const history = staticData.sessions[sessionKey];

async function requestJson(method, url, headers, bodyObj) {
  const opts = {
    method,
    url,
    headers: headers || {},
    json: true,
    timeout: 20000,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  };
  if (bodyObj != null) {
    opts.body = bodyObj;
  }
  const res = await this.helpers.httpRequest.call(this, opts);
  // n8n may return { body, statusCode } or just body depending on version
  if (res && typeof res === 'object' && 'statusCode' in res) {
    return { status: res.statusCode, data: res.body };
  }
  return { status: 200, data: res };
}

const ERROR_ZH = {
  USER_NOT_FOUND: `搵唔到呢個電話嘅會員帳戶。請先註冊：${REGISTER_URL}`,
  STORE_NOT_FOUND: '搵唔到呢間分店，請講「荔枝角」或「尖沙咀／iSQUARE」。',
  STORE_QUERY_REQUIRED: '請提供分店名稱。',
  COURT_NOT_FOUND: '搵唔到呢個場地。',
  COURT_UNAVAILABLE: '場地暫時未能預約。',
  COURT_CLOSED: '呢個時段唔係營業時間。',
  PAST_DATE: '唔可以預約過去嘅日期。',
  DATE_TOO_FAR: '超出可預約日數上限。',
  TIME_CONFLICT: '呢個時段已被預約，請另揀時間或場地。',
  DURATION_TOO_SHORT: '最少要預約 1 小時。',
  DURATION_TOO_LONG: '最多可預約 2 小時。',
  INSUFFICIENT_BALANCE: '積分不足，請先充值再預約。',
  INVALID_TOTAL_PLAYERS: '人數必須係 1–8 人。',
};

function explainBotError(payload) {
  if (!payload || typeof payload !== 'object') return '服務暫時忙碌，請稍後再試。';
  const code = payload.code;
  if (code && ERROR_ZH[code]) {
    let msg = ERROR_ZH[code];
    if (code === 'INSUFFICIENT_BALANCE' && payload.details) {
      msg += `（需要 ${payload.details.required}，餘額 ${payload.details.available}）`;
    }
    return msg;
  }
  return payload.message || '操作失敗，請稍後再試。';
}

async function botGet(path) {
  return requestJson.call(this, 'GET', `${BOT_BASE}${path}`, { 'X-Bot-Key': BOT_KEY });
}
async function botPost(path, body) {
  return requestJson.call(this, 'POST', `${BOT_BASE}${path}`, { 'X-Bot-Key': BOT_KEY }, body);
}

const tools = [
  {
    type: 'function',
    function: {
      name: 'get_balance',
      description: '用 WhatsApp 電話查會員積分',
      parameters: { type: 'object', properties: {} },
    },
  },
  {
    type: 'function',
    function: {
      name: 'get_stores',
      description: '列出分店（含別名）',
      parameters: { type: 'object', properties: {} },
    },
  },
  {
    type: 'function',
    function: {
      name: 'resolve_store',
      description: '用店名／地址／別名解析 storeId（尖沙咀、TST、iSQUARE、荔枝角等）',
      parameters: {
        type: 'object',
        properties: { q: { type: 'string', description: '例如 荔枝角、尖沙咀、iSQUARE、TST' } },
        required: ['q'],
      },
    },
  },
  {
    type: 'function',
    function: {
      name: 'list_activities',
      description: '列出活動中心即將開始／進行中的活動（標題、時間、地點、費用、剩餘名額）',
      parameters: {
        type: 'object',
        properties: {
          store: { type: 'string', description: '可選：分店名／別名篩選，例如 尖沙咀 或 iSQUARE' },
          limit: { type: 'integer', description: '最多幾筆，預設 15，上限 30' },
        },
      },
    },
  },
  {
    type: 'function',
    function: {
      name: 'check_availability',
      description: '查指定店鋪日期時段所有場地空缺',
      parameters: {
        type: 'object',
        properties: {
          storeId: { type: 'string' },
          date: { type: 'string', description: 'YYYY-MM-DD' },
          startTime: { type: 'string', description: 'HH:MM' },
          endTime: { type: 'string', description: 'HH:MM 或 24:00' },
          courtType: { type: 'string', description: 'optional: competition|training|solo|dink' },
        },
        required: ['storeId', 'date', 'startTime', 'endTime'],
