    },
  },
  {
    type: 'function',
    function: {
      name: 'propose_booking',
      description: '暫存待確認預約摘要（未扣積分）。用戶回「確認」後才 create_booking。',
      parameters: {
        type: 'object',
        properties: {
          courtId: { type: 'string' },
          courtName: { type: 'string' },
          date: { type: 'string' },
          startTime: { type: 'string' },
          endTime: { type: 'string' },
          totalPlayers: { type: 'integer', minimum: 1, maximum: 8 },
          estimatedPoints: { type: 'number' },
          includeSoloCourt: { type: 'boolean' },
        },
        required: ['courtId', 'date', 'startTime', 'endTime', 'totalPlayers'],
      },
    },
  },
  {
    type: 'function',
    function: {
      name: 'create_booking',
      description: '僅在用戶已回覆「確認」且有 pending proposal 時呼叫。會即時扣積分。',
      parameters: {
        type: 'object',
        properties: { confirmToken: { type: 'string', description: 'propose_booking 回傳的 token' } },
        required: ['confirmToken'],
      },
    },
  },
];

const systemPrompt = `你是 PickleVibes WhatsApp 客服（香港 24/7 智能匹克球）。繁中為主。簡短直接。

規則：
- 禁止估計價錢／空位／積分／日期／時間。缺資料就追問，唔好自行假設。
- 查積分、空缺、訂場、活動必須先 call tools，只用工具結果回答。
- 禁止回「請等我查／正在查詢／稍等」這類進度句。用戶只會收到你這一則最終回覆，冇第二則跟進。
- 用戶只講分店（例如 iSQUARE／尖沙咀）但未講日期或時間 → 只問清楚日期同開始時間／時長，唔好 call availability。
- 「尖沙咀」「TST」「iSQUARE」都係同一間尖沙咀店；「荔枝角」「LCK」係總店。resolve_store／get_stores 會對地址同別名。
- 問活動／活動中心／有咩課／體驗班 → 必須 call list_activities，列出標題、時間、地點、費用、剩餘名額，並附上每項 detailUrl（完整連結）。唔好只叫人去官網而唔列活動；冇活動先講暫時冇可報名活動並可附 activitiesHubUrl。
- 工具失敗時，只可轉述工具返回的 error。
- USER_NOT_FOUND → 引導註冊 ${REGISTER_URL}，唔好訂場。
- 時長只可 1 或 2 小時。
- 訂場前用 propose_booking，等用戶回「確認」兩字先 create_booking。「好／ok／book」唔算確認。
- 禁止編造電話、電郵、網址。官方聯絡只可講：電話 +852 6190 2761，電郵 info@picklevibes.hk。網站 ${REGISTER_URL}。
- 當前用戶電話：${from}`;

history.push({ role: 'user', content: userText });
while (history.length > 16) history.shift();

const messages = [{ role: 'system', content: systemPrompt }, ...history];

async function runTool(name, args) {
  try {
    if (name === 'get_balance') {
      const res = await botGet.call(this, `/api/bot/balance?phone=${encodeURIComponent(from)}`);
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      return { ok: true, data: res.data.data || res.data };
    }
    if (name === 'get_stores') {
      const res = await botGet.call(this, '/api/bot/stores');
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      return { ok: true, data: res.data.data || res.data };
    }
    if (name === 'resolve_store') {
      const res = await botGet.call(this, `/api/bot/stores/resolve?q=${encodeURIComponent(args.q || '')}`);
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      return { ok: true, data: res.data.data || res.data };
    }
    if (name === 'list_activities') {
      const parts = [];
      if (args.store) parts.push(`store=${encodeURIComponent(args.store)}`);
      if (args.limit) parts.push(`limit=${encodeURIComponent(String(args.limit))}`);
      const qs = parts.length ? `?${parts.join('&')}` : '';
      const res = await botGet.call(this, `/api/bot/activities${qs}`);
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      return { ok: true, data: res.data.data || res.data };
    }
    if (name === 'check_availability') {
      const parts = [
        `store=${encodeURIComponent(args.storeId || '')}`,
        `date=${encodeURIComponent(args.date || '')}`,
        `startTime=${encodeURIComponent(args.startTime || '')}`,
        `endTime=${encodeURIComponent(args.endTime || '')}`,
      ];
      if (args.courtType) parts.push(`courtType=${encodeURIComponent(args.courtType)}`);
      const res = await botGet.call(this, `/api/bot/availability?${parts.join('&')}`);
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      return { ok: true, data: res.data.data || res.data };
    }
    if (name === 'propose_booking') {
      const token = `pb_${from}_${Date.now()}`;
      staticData.pendingBookings[token] = {
        phone: from,
        court: args.courtId,
        courtName: args.courtName || '',
        date: args.date,
        startTime: args.startTime,
        endTime: args.endTime,
        totalPlayers: args.totalPlayers,
        estimatedPoints: args.estimatedPoints,
        includeSoloCourt: Boolean(args.includeSoloCourt),
        createdAt: Date.now(),
      };
      return {
        ok: true,
        data: {
          confirmToken: token,
          summary: `${args.courtName || args.courtId}｜${args.date} ${args.startTime}-${args.endTime}｜${args.totalPlayers}人｜約 ${args.estimatedPoints ?? '?'} 積分`,
          instruction: '請用戶回覆「確認」兩字後，再用同一個 confirmToken 呼叫 create_booking',
        },
      };
    }
    if (name === 'create_booking') {
      const normalized = String(userText || '').replace(/\s/g, '');
      const confirmed = normalized === '確認' || normalized.toLowerCase() === 'confirm';
      if (!confirmed) {
        return { ok: false, error: '用戶本則訊息未包含「確認」，不可扣積分。請先請用戶回覆「確認」。' };
      }
      const pending = staticData.pendingBookings[args.confirmToken];
      if (!pending || pending.phone !== from) {
        return { ok: false, error: '找不到待確認預約，請重新揀場同 propose_booking。' };
      }
      if (Date.now() - pending.createdAt > 30 * 60 * 1000) {
        delete staticData.pendingBookings[args.confirmToken];
        return { ok: false, error: '確認已逾時，請重新查空缺。' };
      }
      const res = await botPost.call(this, '/api/bot/booking', {
        phone: pending.phone,
        court: pending.court,
        date: pending.date,
        startTime: pending.startTime,
        endTime: pending.endTime,
        totalPlayers: pending.totalPlayers,
        includeSoloCourt: pending.includeSoloCourt,
        specialRequests: 'WhatsApp LLM 預約',
        source: 'whatsapp_bot',
      });
      if (res.status >= 400) return { ok: false, error: explainBotError(res.data), raw: res.data };
      delete staticData.pendingBookings[args.confirmToken];
      return { ok: true, data: res.data.data || res.data };
    }
    return { ok: false, error: `未知工具 ${name}` };
  } catch (e) {
    return { ok: false, error: e.message || String(e) };
  }
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function isRetryableAiStatus(status) {
  return status === 429 || status === 408 || status >= 500;
}

function aiErrorText(aiRes) {
  return aiRes?.data?.error?.message || aiRes?.data?.message || JSON.stringify(aiRes?.data || {}).slice(0, 300);
}

async function callChatCompletions(model) {
  return requestJson.call(
    this,
    'POST',
    `${OPENAI_BASE}/chat/completions`,
    { Authorization: `Bearer ${OPENAI_KEY}`, 'Content-Type': 'application/json' },
    {
      model,
      messages,
      tools,
      tool_choice: 'auto',
      temperature: 0.2,
    }
  );
}

let reply = '系統暫時忙碌，請稍後再試。如需協助可致電 +852 6190 2761。';
let activeModel = MODEL_CHAIN[0];
let modelIndex = 0;
let lastAiError = '';

for (let round = 0; round < 8; round++) {
  let aiRes = await callChatCompletions.call(this, activeModel);

  // retry once on rate-limit / upstream blip
  if (aiRes.status >= 400 && isRetryableAiStatus(aiRes.status)) {
    await sleep(1200);
    aiRes = await callChatCompletions.call(this, activeModel);
  }

  // switch to next fallback model
  while (aiRes.status >= 400 && modelIndex < MODEL_CHAIN.length - 1) {
    lastAiError = `model=${activeModel} status=${aiRes.status} ${aiErrorText(aiRes)}`;
    modelIndex += 1;
    activeModel = MODEL_CHAIN[modelIndex];
    await sleep(400);
    aiRes = await callChatCompletions.call(this, activeModel);
    if (aiRes.status >= 400 && isRetryableAiStatus(aiRes.status)) {
      await sleep(1200);
      aiRes = await callChatCompletions.call(this, activeModel);
    }
  }

  if (aiRes.status >= 400) {
    lastAiError = `model=${activeModel} status=${aiRes.status} ${aiErrorText(aiRes)}`;
    console.log('AI all models failed:', lastAiError);
    reply = '系統暫時忙碌，請稍後再試。如需協助可致電 +852 6190 2761。';
    break;
  }

  const choice = aiRes.data?.choices?.[0]?.message;
  if (!choice) {
    // empty response: try next model once
    if (modelIndex < MODEL_CHAIN.length - 1) {
      modelIndex += 1;
      activeModel = MODEL_CHAIN[modelIndex];
      continue;
    }
    reply = '暫時未能產生回覆，請稍後再試。';
    break;
  }

  messages.push(choice);

  const toolCalls = choice.tool_calls || [];
  if (!toolCalls.length) {
    let text = String(choice.content || '').trim() || '收到。';
    const fakeProgress = /(正在查詢|請稍等|請等我|幫你查下|查詢空缺|稍等～|稍等~)/.test(text);
    if (fakeProgress) {
      // model pretended to check without tools; ask for missing info instead
      text = '想幫你查 iSQUARE／分店空缺，請話我知日期（例如 2026-10-18）同開始時間、想訂幾耐（1 或 2 小時）。';
      // remove the fake assistant turn from messages so history stays clean
      messages.pop();
    }
    reply = text;
    history.push({ role: 'assistant', content: reply });
    break;
  }

  for (const tc of toolCalls) {
    let args = {};
    try { args = JSON.parse(tc.function?.arguments || '{}'); } catch { args = {}; }
    const result = await runTool.call(this, tc.function?.name, args);
    messages.push({
      role: 'tool',
      tool_call_id: tc.id,
      content: JSON.stringify(result),
    });
  }
}

staticData.sessions[sessionKey] = history.slice(-16);

return [{ json: { from, reply: reply.slice(0, 4000), messageId } }];
